"""Encoding contract shared by the bot (inference) and research/ (training).

Everything is expressed from the perspective of the player to move: for Black
the board is mirrored vertically, so "own" pieces always start on ranks 1-2.
Changing anything here invalidates trained weights; bump FORMAT_VERSION.
"""
from __future__ import annotations

import chess
import numpy as np

FORMAT_VERSION = 1

# Hidden-square classes generated by the denoiser.
EMPTY = 0
ENEMY_TYPES = (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN, chess.KING)
NUM_CLASSES = 1 + len(ENEMY_TYPES)

# Extra input tokens: MASK marks a hidden square not yet generated, VISIBLE a
# square whose content comes from the context planes instead.
MASK = NUM_CLASSES
VISIBLE = NUM_CLASSES + 1
NUM_TOKENS = NUM_CLASSES + 2
IGNORE_LABEL = -100

# Context planes:
#   0-5   own P N B R Q K           6-11  visible enemy P N B R Q K
#   12    hidden ('?')              13    visible empty ('-')
#   14-19 remembered enemy P..K on currently hidden squares, decayed by age
#   20    staleness of each hidden square (0 = seen last ply, 1 = never seen)
#   21-22 own kingside / queenside castling right (constant planes)
#   23    playing White (constant plane)
CONTEXT_PLANES = 24
MEMORY_DECAY = 0.9
STALENESS_HORIZON = 40.0

OBSERVATION_CHARACTERS = frozenset("?-PNBRQKpnbrqk")


def orient(square: int, side: chess.Color) -> int:
    """Map a real square to the side-relative index used by every tensor."""
    return square if side == chess.WHITE else chess.square_mirror(square)


def class_of(symbol: str, side: chess.Color) -> int | None:
    """Class index of an enemy piece symbol, EMPTY for '-', None otherwise."""
    if symbol == "-":
        return EMPTY
    if symbol == "?":
        return None
    piece = chess.Piece.from_symbol(symbol)
    if piece.color == side:
        return None
    return ENEMY_TYPES.index(piece.piece_type) + 1


def piece_of(cls: int, side: chess.Color) -> chess.Piece | None:
    return None if cls == EMPTY else chess.Piece(ENEMY_TYPES[cls - 1], not side)


def encode_context(tracker) -> np.ndarray:
    """Encode a GameTracker's current knowledge as float32[CONTEXT_PLANES, 8, 8]."""
    side, view, ply = tracker.side, tracker.current, tracker.ply
    planes = np.zeros((CONTEXT_PLANES, 8, 8), dtype=np.float32)
    for square, symbol in enumerate(view):
        index = orient(square, side)
        row, col = divmod(index, 8)
        if symbol == "?":
            planes[12, row, col] = 1
            remembered = tracker.last_seen[square]
            if remembered is not None:
                age = ply - tracker.last_seen_ply[square]
                cls = class_of(remembered, side)
                planes[14 + cls - 1, row, col] = MEMORY_DECAY ** age
            seen = tracker.last_visible_ply[square]
            planes[20, row, col] = 1.0 if seen < 0 else min(1.0, (ply - seen) / STALENESS_HORIZON)
        elif symbol == "-":
            planes[13, row, col] = 1
        else:
            piece = chess.Piece.from_symbol(symbol)
            offset = 0 if piece.color == side else 6
            planes[offset + piece.piece_type - 1, row, col] = 1
    rank = 0 if side else 7
    planes[21] = float(bool(tracker.rights & chess.BB_SQUARES[chess.square(7, rank)]))
    planes[22] = float(bool(tracker.rights & chess.BB_SQUARES[chess.square(0, rank)]))
    planes[23] = float(side == chess.WHITE)
    return planes


def encode_tokens(view: str, side: chess.Color) -> np.ndarray:
    """int64[64]: MASK on hidden squares, VISIBLE elsewhere (side-relative order)."""
    tokens = np.full(64, VISIBLE, dtype=np.int64)
    for square, symbol in enumerate(view):
        if symbol == "?":
            tokens[orient(square, side)] = MASK
    return tokens


def encode_labels(board: chess.Board, view: str, side: chess.Color) -> np.ndarray:
    """Training targets: true class on hidden squares, IGNORE_LABEL elsewhere."""
    labels = np.full(64, IGNORE_LABEL, dtype=np.int64)
    for square, symbol in enumerate(view):
        if symbol != "?":
            continue
        piece = board.piece_at(square)
        if piece is None:
            labels[orient(square, side)] = EMPTY
        elif piece.color == side:
            raise ValueError("Own pieces are always visible; observation is inconsistent")
        else:
            labels[orient(square, side)] = ENEMY_TYPES.index(piece.piece_type) + 1
    return labels
